def make_palindrome(s: str) -> str:
    if not s:
        return ""

    n = len(s)
    # Find the longest palindromic suffix
    for i in range(n):
        if s[i:] == s[i:][::-1]:
            # Append the reverse of the prefix to the end of the string
            return s + s[:i][::-1]
    # In case the whole string is a palindrome, return it
    return s
