        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            # If balance goes negative, parentheses are not balanced
            if balance < 0:
                return False
        # If balance is zero, parentheses are balanced
        return balance == 0

    # Check both possible concatenations
    if is_balanced(lst[0] + lst[1]) or is_balanced(lst[1] + lst[0]):
        return 'Yes'
    else:
        return 'No'
