    all_values = set(range(1, N * N + 1))
    path = []

    def dfs(current, visited):
        nonlocal path
        if len(visited) == k:
            path = sorted(visited)
            return

        for i in range(N):
            for j in range(N):
                if grid[i][j] not in visited and grid[i][j] in all_values:
                    all_values.remove(grid[i][j])
                    visited.add(grid[i][j])
                    dfs(current + [(i, j)], visited)
                    all_values.add(grid[i][j])
                    visited.remove(grid[i][j])

