        return len(set(word))

    max_unique_count = 0
    max_word = ""

    for word in words:
        unique_count = count_unique_chars(word)
        if unique_count > max_unique_count or (unique_count == max_unique_count and word < max_word):
            max_unique_count = unique_count
            max_word = word

    return max_word
